func generateParenthesis(n int) []string {
	res := []string{}
	var dfs func(curStr string, left, right, n int)
	dfs = func(curStr string, left, right, n int) {
		if left == n && right == n {
			res = append(res, curStr)
			return
		}
		if left < right {
			return
		}
		if left < n {
			dfs(curStr+"(", left+1, right, n)
		}
		if right < n {
			dfs(curStr+")", left, right+1, n)
		}
	}
	dfs("", 0, 0, n)
	return res
}

