func generateParenthesis(n int) []string {
	ans := []string{}
	var generate func(A []byte)
	generate = func(A []byte) {
		if len(A) == 2*n {
			if valid(A) {
				ans = append(ans, string(A))
			}
			return
		}
		A = append(A, '(')
		generate(A)
		A = A[:len(A)-1]
		A = append(A, ')')
		generate(A)
		A = A[:len(A)-1]
	}
	var valid func(A []byte) bool
	valid = func(A []byte) bool {
		bal := 0
		for _, c := range A {
			if c == '(' {
				bal++
			} else {
				bal--
			}
			if bal < 0 {
				return false
			}
		}
		return bal == 0
	}
	generate([]byte{})
	return ans
}

func generateParenthesis(n int) []string {
	ans := []string{}
	var backtrack func(S []byte, left, right int)
	backtrack = func(S []byte, left, right int) {
		if len(S) == 2*n {
			ans = append(ans, string(S))
			return
		}
		if left < n {
			S = append(S, '(')
			backtrack(S, left+1, right)
			S = S[:len(S)-1]
		}
		if right < left {
			S = append(S, ')')
			backtrack(S, left, right+1)
			S = S[:len(S)-1]
		}
	}
	backtrack([]byte{}, 0, 0)
	return ans
}

func generateParenthesis(n int) []string {
	memo := map[int][]string{}
	var gen func(n int) []string
	gen = func(n int) []string {
		if v, ok := memo[n]; ok {
			return v
		}
		if n == 0 {
			return []string{""}
		}
		ans := []string{}
		for c := 0; c < n; c++ {
			for _, left := range gen(c) {
				for _, right := range gen(n - 1 - c) {
					ans = append(ans, "("+left+")"+right)
				}
			}
		}
		memo[n] = ans
		return ans
	}
	return gen(n)
}
